    for (j = 0; j < nj; j++)
      C[i][j] = (DATA_TYPE) ((i*j+1) % ni) / ni;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) (i*(j+1) % nk) / nk;
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) (i*(j+2) % nj) / nj;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nj,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gemm[[gnu::flatten, gnu::noinline]](int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j, k;

//BLAS PARAMS
//TRANSA = 'N'
//TRANSB = 'N'
// => Form C := alpha*A*B + beta*C,
//A is NIxNK
//B is NKxNJ
//C is NIxNJ
#pragma scop

  /*
   * Optimized GEMM with cache blocking and register tiling.
   *
   * 1. SEPARATED BETA SCALING: Split into its own pass so the matrix
   *    multiply can be freely tiled in all three dimensions.
   *
   * 2. LOOP TILING: i, j, k tiled for L1/L2 cache residency.
   *    - C tile (TI x TJ) = 32x128 x sizeof = ~32KB -> L1
   *    - B tile (TK x TJ) = 64x128 x sizeof = ~64KB -> L2
   *    - A tile (TI x TK) = 32x64  x sizeof = ~16KB -> L1/L2
   *
   * 3. TILE ORDER jj->kk->ii: The B tile [kk:+TK][jj:+TJ] stays
   *    resident in L2 while all i-tiles are processed against it.
   *
   * 4. REGISTER BLOCKING (RI=4): For each k, 4 rows of C are updated
   *    simultaneously. B[k][j] is loaded once and reused for 4 FMAs,
   *    cutting B bandwidth demand by 4x.
   *
   * 5. INNER ORDER k->i(blocked)->j: The innermost j loop has stride-1
   *    access on both C and B, enabling SIMD auto-vectorization.
   */

  /* Tile sizes for x86-64 (L1d ~32KB, L2 ~256KB per core) */
  #define GEMM_TI 32
  #define GEMM_TJ 128
  #define GEMM_TK 64
  #define GEMM_RI 4    /* rows of C processed per register block */

  /* Phase 1: Scale C by beta (streaming pass, auto-vectorized) */
  for (i = 0; i < _PB_NI; i++)
    for (j = 0; j < _PB_NJ; j++)
      C[i][j] *= beta;

  /* Phase 2: Tiled accumulation C += alpha * A * B */
  {
    int ii, jj, kk;

    for (jj = 0; jj < _PB_NJ; jj += GEMM_TJ) {
      int j_end = (jj + GEMM_TJ < _PB_NJ) ? jj + GEMM_TJ : _PB_NJ;

      for (kk = 0; kk < _PB_NK; kk += GEMM_TK) {
        int k_end = (kk + GEMM_TK < _PB_NK) ? kk + GEMM_TK : _PB_NK;

        /* B tile [kk:k_end][jj:j_end] is now hot in L2 */
        for (ii = 0; ii < _PB_NI; ii += GEMM_TI) {
          int i_end = (ii + GEMM_TI < _PB_NI) ? ii + GEMM_TI : _PB_NI;

          for (k = kk; k < k_end; k++) {

            /* Main register-blocked loop: 4 C-rows share each B load */
            for (i = ii; i + GEMM_RI <= i_end; i += GEMM_RI) {
              DATA_TYPE a0 = alpha * A[i][k];
              DATA_TYPE a1 = alpha * A[i + 1][k];
              DATA_TYPE a2 = alpha * A[i + 2][k];
              DATA_TYPE a3 = alpha * A[i + 3][k];
              /* Stride-1 j loop: compiler will auto-vectorize (AVX2/SSE) */
              #pragma GCC ivdep
              for (j = jj; j < j_end; j++) {
                DATA_TYPE bval = B[k][j];
                C[i][j]     += a0 * bval;
                C[i + 1][j] += a1 * bval;
                C[i + 2][j] += a2 * bval;
                C[i + 3][j] += a3 * bval;
              }
            }

            /* Cleanup for remaining rows (fewer than GEMM_RI) */
            for (; i < i_end; i++) {
              DATA_TYPE a0 = alpha * A[i][k];
              #pragma GCC ivdep
              for (j = jj; j < j_end; j++)
                C[i][j] += a0 * B[k][j];
            }

          } /* k */
        } /* ii */
      } /* kk */
    } /* jj */
  }

  #undef GEMM_TI
  #undef GEMM_TJ
  #undef GEMM_TK
  #undef GEMM_RI

#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,NI,NJ,ni,nj);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,NI,NK,ni,nk);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,NK,NJ,nk,nj);

  /* Initialize array(s). */
  init_array (ni, nj, nk, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gemm (ni, nj, nk,
	       alpha, beta,
	       POLYBENCH_ARRAY(C),
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(ni, nj,  POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
