  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++)
      C[i][j] = (DATA_TYPE) ((i*j+1) % ni) / ni;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) (i*(j+1) % nk) / nk;
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) (i*(j+2) % nj) / nj;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nj,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gemm[[gnu::flatten, gnu::noinline]](int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j, k;
  int ii, jj, kk;

  /* ---------------------------------------------------------------
   * Optimized GEMM: C = alpha * A * B + beta * C
   *
   * 1) Cache tiling: i, j, k loops are tiled so the working set
   *    fits in the L2 cache (~256KB per core):
   *      C tile: TI x TJ = 128 x 128 = 128KB
   *      A tile: TI x TK = 128 x  32 =  32KB
   *      B tile: TK x TJ =  32 x 128 =  32KB
   *      Total working set: 192KB (fits in L2 with headroom)
   *
   *    Tile loop order: ii -> jj -> kk (k innermost among tiles).
   *    Each C tile stays in L2 across all kk iterations, so C is
   *    read from main memory only once overall.
   *
   * 2) Register blocking: i-dimension unrolled by RI=4. Each B[k][j]
   *    value loaded is reused across 4 rows of C, increasing
   *    arithmetic intensity and reducing memory bandwidth pressure.
   *
   * 3) Fused beta scaling: Beta scaling of each C tile is done
   *    immediately before its accumulation loop, keeping the tile
   *    warm in L2 cache and avoiding a separate full pass over C.
   *
   * 4) Hoisted multiply: alpha*A[i][k] is computed once per (i,k)
   *    pair and reused across all j in the inner vectorizable loop.
   *
   * Inner loop order: i -> k -> j. The innermost j loop has stride-1
   * access on both C[][] and B[][], enabling auto-vectorization.
   * --------------------------------------------------------------- */

  #define TI  128  /* tile height (rows of C, A)    */
  #define TJ  128  /* tile width  (cols of C, B)    */
  #define TK   32  /* tile depth  (reduction dim k) */
  #define RI    4  /* register blocking factor for i */

//BLAS PARAMS
//TRANSA = 'N'
//TRANSB = 'N'
// => Form C := alpha*A*B + beta*C,
//A is NIxNK
//B is NKxNJ
//C is NIxNJ
#pragma scop
  for (ii = 0; ii < _PB_NI; ii += TI) {
    /* Tile boundary for i, clamped to matrix dimension */
    int i_end = ii + TI;
    if (i_end > _PB_NI) i_end = _PB_NI;
    /* Largest index aligned to RI within this i-tile */
    int i_blk = ii + ((i_end - ii) / RI) * RI;

    for (jj = 0; jj < _PB_NJ; jj += TJ) {
      int j_end = jj + TJ;
      if (j_end > _PB_NJ) j_end = _PB_NJ;

      /* Scale this C tile by beta. Done per-tile right before
       * accumulation so the tile is loaded into L2 and stays
       * warm for the subsequent kk loop iterations. */
      for (i = ii; i < i_end; i++)
        for (j = jj; j < j_end; j++)
          C[i][j] *= beta;

      /* Accumulate: C_tile += alpha * A_panel * B_panel.
       * kk is innermost tile loop so C tile remains in L2. */
      for (kk = 0; kk < _PB_NK; kk += TK) {
        int k_end = kk + TK;
        if (k_end > _PB_NK) k_end = _PB_NK;

        /* Register-blocked micro-kernel: process RI=4 rows at once.
         * Each B[k][j] load is reused for 4 FMA operations on
         * 4 different C rows, improving FLOPs-per-byte. */
        for (i = ii; i < i_blk; i += RI) {
          for (k = kk; k < k_end; k++) {
            DATA_TYPE a0 = alpha * A[i    ][k];
            DATA_TYPE a1 = alpha * A[i + 1][k];
            DATA_TYPE a2 = alpha * A[i + 2][k];
            DATA_TYPE a3 = alpha * A[i + 3][k];
            /* Innermost j loop: stride-1 on C and B for vectorization */
            for (j = jj; j < j_end; j++) {
              DATA_TYPE bkj = B[k][j];
              C[i    ][j] += a0 * bkj;
              C[i + 1][j] += a1 * bkj;
              C[i + 2][j] += a2 * bkj;
              C[i + 3][j] += a3 * bkj;
            }
          }
        }

        /* Handle remaining rows not divisible by RI */
        for (i = i_blk; i < i_end; i++) {
          for (k = kk; k < k_end; k++) {
            DATA_TYPE aik = alpha * A[i][k];
            for (j = jj; j < j_end; j++)
              C[i][j] += aik * B[k][j];
          }
        }
      } /* kk */
    } /* jj */
  } /* ii */
#pragma endscop

  #undef TI
  #undef TJ
  #undef TK
  #undef RI
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
