/*
 * Cache tile sizes for the optimized GEMM kernel.
 *
 * Per-tile working set (assuming 8-byte doubles):
 *   C tile: BI x BJ = 32 x 64 = 2048 doubles = 16 KB  (fits in L1)
 *   A tile: BI x BK = 32 x 64 = 2048 doubles = 16 KB  (fits in L1)
 *   B tile: BK x BJ = 64 x 64 = 4096 doubles = 32 KB  (fits in L2)
 *   Total: ~64 KB — comfortably within L2 (typically 256 KB+)
 */
#define BI 32
#define BK 64
#define BJ 64


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gemm[[gnu::flatten, gnu::noinline]](int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j, k;

//BLAS PARAMS
//TRANSA = 'N'
//TRANSB = 'N'
// => Form C := alpha*A*B + beta*C,
//A is NIxNK
//B is NKxNJ
//C is NIxNJ
#pragma scop

  /*
   * Optimized GEMM with cache tiling and register blocking.
   *
   * Key optimizations:
   * 1. Beta-scaling separated from multiply-add for clean tiling.
   *    (Valid because scaling is independent of k and independent per element.)
   * 2. Three-level loop tiling (ii, jj, kk) for L1/L2 cache locality.
   *    Tile loop order: ii -> jj -> kk, so the C tile stays in L1 cache
   *    across all kk iterations (accumulating contributions in-place).
   * 3. Register blocking: 4 rows of i processed together per micro-kernel.
   *    B[k][j] is loaded once and reused for 4 rows of C, giving a 4x
   *    reduction in B memory traffic within the micro-kernel.
   * 4. alpha * A[i][k] hoisted out of the innermost j-loop.
   * 5. Innermost j-loop accesses C and B contiguously in memory,
   *    enabling auto-vectorization (AVX2/AVX-512).
   */

  /* Phase 1: Scale C by beta — simple streaming pass */
  for (i = 0; i < _PB_NI; i++) {
    for (j = 0; j < _PB_NJ; j++)
      C[i][j] *= beta;
  }

  /* Phase 2: Tiled C += alpha * A * B */
  {
    int ii, jj, kk;

    for (ii = 0; ii < _PB_NI; ii += BI) {
      /* Clamp tile upper bound to matrix dimension */
      int i_end = (ii + BI < _PB_NI) ? ii + BI : _PB_NI;

      for (jj = 0; jj < _PB_NJ; jj += BJ) {
        int j_end = (jj + BJ < _PB_NJ) ? jj + BJ : _PB_NJ;

        /* kk is innermost tile loop: C[ii..i_end)[jj..j_end) remains
         * in L1 cache while we accumulate contributions from each k-tile */
        for (kk = 0; kk < _PB_NK; kk += BK) {
          int k_end = (kk + BK < _PB_NK) ? kk + BK : _PB_NK;

          /*
           * 4-way register-blocked micro-kernel.
           * For each (k, j), B[k][j] is loaded once and used for 4 C rows.
           */
          for (i = ii; i + 3 < i_end; i += 4) {
            for (k = kk; k < k_end; k++) {
              /* Hoist scalar alpha*A[i+r][k] outside j-loop */
              DATA_TYPE a0 = alpha * A[i    ][k];
              DATA_TYPE a1 = alpha * A[i + 1][k];
              DATA_TYPE a2 = alpha * A[i + 2][k];
              DATA_TYPE a3 = alpha * A[i + 3][k];

              /* Contiguous j-access: auto-vectorizable.
               * ivdep confirms no loop-carried dependency on j. */
              #pragma GCC ivdep
              for (j = jj; j < j_end; j++) {
                DATA_TYPE bkj = B[k][j];
                C[i    ][j] += a0 * bkj;
                C[i + 1][j] += a1 * bkj;
                C[i + 2][j] += a2 * bkj;
                C[i + 3][j] += a3 * bkj;
              }
            }
          }

          /* Remainder rows when (i_end - ii) is not divisible by 4 */
          for (; i < i_end; i++) {
            for (k = kk; k < k_end; k++) {
              DATA_TYPE aval = alpha * A[i][k];
              #pragma GCC ivdep
              for (j = jj; j < j_end; j++) {
                C[i][j] += aval * B[k][j];
              }
            }
          }

        } /* end kk */
      } /* end jj */
    } /* end ii */
  }

#pragma endscop

}


