/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gemm[[gnu::flatten, gnu::noinline]](int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j, k;

//BLAS PARAMS
//TRANSA = 'N'
//TRANSB = 'N'
// => Form C := alpha*A*B + beta*C,
//A is NIxNK
//B is NKxNJ
//C is NIxNJ

  /*
   * Cache tile sizes chosen so combined working set fits in L2 (~160KB):
   *   C tile: TI * TJ * 8 =  64 KB  (read-modify-write, stays in cache for kk loop)
   *   B tile: TK * TJ * 8 =  64 KB  (read-only, reused across i iterations)
   *   A tile: TI * TK * 8 =  32 KB  (read-only)
   */
  #define GEMM_TI 64   /* tile rows of C and A */
  #define GEMM_TJ 128  /* tile columns of C and B; inner vectorized dimension */
  #define GEMM_TK 64   /* tile along reduction (k) dimension */
  #define GEMM_RI 4    /* register-blocking factor on i-dimension */

#pragma scop
  /*
   * Three-level tiled GEMM with fused beta-scaling and register blocking.
   *
   * Outer tile loops (ii, jj): iterate over C tiles.
   *   For each C tile, beta-scaling is done immediately so the tile
   *   is warm in cache before the multiply-accumulate begins.
   *
   * Middle tile loop (kk): iterates over the reduction dimension.
   *   The C tile stays in L2 across all kk iterations.
   *
   * Inner loops (i, k, j): the compute micro-kernel.
   *   - i is unrolled 4-way so B[k][j] is loaded once and applied
   *     to 4 rows of C (reduces B memory traffic by ~4x).
   *   - alpha * A[i][k] is hoisted out of the j-loop (loop-invariant).
   *   - The j-loop is the innermost vectorized loop with sequential
   *     access to both C[i][j] and B[k][j].
   */
  for (int ii = 0; ii < _PB_NI; ii += GEMM_TI) {
    const int i_end = (ii + GEMM_TI < _PB_NI) ? (ii + GEMM_TI) : _PB_NI;

    for (int jj = 0; jj < _PB_NJ; jj += GEMM_TJ) {
      const int j_end = (jj + GEMM_TJ < _PB_NJ) ? (jj + GEMM_TJ) : _PB_NJ;

      /* Fused beta-scaling: scale this C tile while it is loaded into cache */
      for (i = ii; i < i_end; i++) {
        #pragma GCC ivdep
        for (j = jj; j < j_end; j++) {
          C[i][j] *= beta;
        }
      }

      /* Accumulate: C_tile += alpha * A_panel * B_panel, over all k-tiles */
      for (int kk = 0; kk < _PB_NK; kk += GEMM_TK) {
        const int k_end = (kk + GEMM_TK < _PB_NK) ? (kk + GEMM_TK) : _PB_NK;

        /*
         * Register-blocked micro-kernel (4 rows of C at a time).
         * Each B[k][j] load is shared across 4 FMA operations,
         * cutting B bandwidth demand by 4x.
         */
        for (i = ii; i + GEMM_RI <= i_end; i += GEMM_RI) {
          for (k = kk; k < k_end; k++) {
            const DATA_TYPE a0 = alpha * A[i + 0][k];
            const DATA_TYPE a1 = alpha * A[i + 1][k];
            const DATA_TYPE a2 = alpha * A[i + 2][k];
            const DATA_TYPE a3 = alpha * A[i + 3][k];
            #pragma GCC ivdep
            for (j = jj; j < j_end; j++) {
              const DATA_TYPE bkj = B[k][j];
              C[i + 0][j] += a0 * bkj;
              C[i + 1][j] += a1 * bkj;
              C[i + 2][j] += a2 * bkj;
              C[i + 3][j] += a3 * bkj;
            }
          }
        }

        /* Cleanup: remaining 0..GEMM_RI-1 rows without register blocking */
        for (; i < i_end; i++) {
          for (k = kk; k < k_end; k++) {
            const DATA_TYPE temp = alpha * A[i][k];
            #pragma GCC ivdep
            for (j = jj; j < j_end; j++) {
              C[i][j] += temp * B[k][j];
            }
          }
        }
      } /* kk */
    } /* jj */
  } /* ii */
#pragma endscop

  #undef GEMM_TI
  #undef GEMM_TJ
  #undef GEMM_TK
  #undef GEMM_RI
